(function (global) {

  try {
    function TinyTel(opts) {
      opts = opts || {};
      var maxTxt = opts.maxTextLen || 60;        // clip long text nodes
      var buf = [];      // JSON objects
      var str = [];      // 1-line serialisations
      var inputs = {};   // {path:{v:'value',t:123,tag:'INPUT'}}

      /* ---------- helpers ---------- */
      function now() { return +new Date(); }
      function clip(t) { return String(t || '').replace(/\s+/g, ' ').trim().slice(0, maxTxt); }
      function push(obj, s) { buf.push(obj); str.push(s); }

      function path(el) {
        if (!el || el === document) { return 'document'; }
        var parts = [];
        while (el && el.nodeType === 1 && parts.length < 5) {
          var n = el.tagName.toLowerCase();
          if (el.id) { parts.unshift(n + '#' + el.id); break; }
          var cls = (el?.className?.baseVal || el?.className || '').split(/\s+/).join('.');
          var nm = el.getAttribute('name') ? '[name="' + el.getAttribute('name') + '"]' : '';
          var idx = [].indexOf.call(el.parentNode ? el.parentNode.children : [], el) + 1;
          if (cls.length && n == 'div') n = '';

          parts.unshift(n + (cls ? '.' + cls : '') + nm + ':nth-child(' + idx + ')');
          el = el.parentNode;
        }
        return parts.join('>');
      }

      document.addEventListener('click', function (ev) {
        var el = ev.target;
        var p = path(el);
        var txt = clip(el.innerText || el.textContent);
        var ts = now();
        push(
          { e: 'c', t: ts, p: p, x: ev.clientX, y: ev.clientY, tx: txt },
          new Date(ts).toLocaleString() + '|c|' + el.tagName + '|' + txt + '|' + p + '|' + ev.clientX + ',' + ev.clientY
        );
      }, true);

      function recordInput(ev) {
        var el = ev.target;
        var tag = el.tagName;
        var type = (el.type || '').toLowerCase();
        if (!(tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT')) { return; }
        var v;
        if (tag === 'SELECT') {
          // multiple selects → comma list
          v = Array.from(el.options)
            .filter(o => o.selected)
            .map(o => o.value)
            .join(',');
        } else if (type === 'checkbox' || type === 'radio') {
          v = el.checked;                   // true / false
        } else {
          v = el.value;                     // text, date, number, etc.
        }
        v = clip(v);
        push(
          { e: 'f', t: now(), p: path(el), v },                      //  e = f(orm)
          new Date().toLocaleString() + '|f|' +
          tag + '|' + v + '|' + path(el)
        );
      }

      window.addEventListener('resize', function () {
        var ts = now();
        push(
          { e: 'w', t: ts, w: window.innerWidth + 'x' + window.innerHeight },
          new Date(ts).toLocaleString() + '|w|' + window.innerWidth + 'x' + window.innerHeight
        );
      });

      // document.addEventListener('input', recordInput, true);
      document.addEventListener('change', recordInput, true);

      (function init() {
        var ts = now();
        push(
          {
            e: 'i', t: ts,
            ua: navigator.userAgent,
            pl: navigator.platform,
            ln: navigator.language,
            w: window.innerWidth + 'x' + window.innerHeight
          },
          new Date(ts).toLocaleString() + '|i|' + navigator.userAgent + '|' + navigator.platform + '|' +
          navigator.language + '|' + window.innerWidth + 'x' + window.innerHeight
        );
      })();

      return {
        /**
         * Returns {json:Array, lines:Array} then empties both buffers.
         * @param {Function=} cb optional → cb(jsonArray, stringArray)
         */
        flush: function (cb) {
          var j = buf.slice();
          var l = str.slice();
          buf.length = 0;
          str.length = 0;
          if (cb) { cb(j, l); }
          return { json: j, lines: l };
        }
      };
    }

    global.TinyTel = TinyTel;
  } catch (e) {
    console.error(e)
  }



})(this);
